    if (u == null) {
        return null;
    }

    // Check if the decode flag is true
    if (decode) {
        // Decode the path component
        try {
            String decodedPath = URLDecoder.decode(u.getPath(), "UTF-8");
            // Split the path component into path segments
            String[] pathSegments = decodedPath.split("/");
            // Create a new list of PathSegmentImpl objects from the path segments
            List<PathSegmentImpl> pathSegmentList = new ArrayList<>(pathSegments.length);
            for (String pathSegment : pathSegments) {
                PathSegmentImpl pathSegmentImpl = new PathSegmentImpl(pathSegment);
                pathSegmentList.add(pathSegmentImpl);
            }
            // Return the list of PathSegmentImpl objects
            return pathSegmentList;
        } catch (UnsupportedEncodingException e) {
            // Handle exception
            throw new RuntimeException(e);
        }
    } else {
        // Return the list of PathSegmentImpl objects
        return Collections.singletonList(new PathSegmentImpl(u.getPath()));
    }
}

