private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Short circuit evaluation using the 'and' predicate
    Predicate<Node> and = x -> predicate.apply(x) && stop.apply(x);
    // Find the first node that satisfies the 'and' predicate
    int index = 0;
    while (index < getSize() && !and.apply(getNode(index))) {
        index++;
    }
    if (index == getSize()) {
        return null;
    }
    // Find the first node that is different from the previous one
    int i = index + 1;
    while (i < getSize() && getNode(i).equals(getNode(i - 1))) {
        i++;
    }
    // Create a circulator to the first matched node
    return new OuterFaceCirculator(this, dir, index, i, stop);
}

