@Override
public Action inspect(AtmosphereResource r) {
    // Check if the AtmosphereResource is destroyed
    if (r.isDestroyed()) {
        // If the resource is destroyed, do not attempt to suspend it
        return Action.CONTINUE;
    }

    // Get the transport type of the AtmosphereResource
    AtmosphereResource.TRANSPORT transport = r.getTransport();

    // Check if the transport type supports suspension
    if (!transport.supportsSuspension()) {
        // If the transport type does not support suspension, do not attempt to suspend it
        return Action.CONTINUE;
    }

    // Create a new logger object
    Logger logger = LoggerFactory.getLogger(this.getClass());

    // Log a message indicating that the AtmosphereResource is being suspended
    logger.info("Suspending AtmosphereResource " + r.getRequest().getServletPath());

    // Suspend the AtmosphereResource
    r.suspend();

    // Return the CONTINUE action
    return Action.CONTINUE;
}

