}

public Class findClass(final String className) throws ClassNotFoundException {
    // First, try to find the class in the current classloader
    Class<?> clazz = Class.forName(className);

    // If the class is not found, try loading it using the parent classloader
    if (clazz == null) {
        clazz = getParent().loadClass(className);
    }

    // If the class is still not found, try loading it using the system classloader
    if (clazz == null) {
        clazz = ClassLoader.getSystemClassLoader().loadClass(className);
    }

    // If the class is still not found, throw an exception
    if (clazz == null) {
        throw new ClassNotFoundException("Class " + className + " could not be found");
    }

    return clazz;
}

