private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the suffix sum and total sum to 0
    int suffixSum = 0;
    long totalSum = 0;

    // Iterate through the list of bounds
    for (int i = 0; i < bounds.size(); i++) {
        // Compute the suffix sum and total sum for the current element
        suffixSum = suffixSum + bounds.get(i);
        totalSum = totalSum + bounds.get(i);
    }

    // Return the computed suffix sum and total sum
    return new Pair<>(Collections.singletonList(suffixSum), totalSum);
}

